(() => {
  const inputElement = document.getElementById("icon-search");
  if (!(inputElement instanceof HTMLInputElement)) return;
  const input: HTMLInputElement = inputElement;
  input.removeAttribute("hidden");

  // Keys are generated by build_search_index() in scripts/generate.py and must
  // match the id attributes in templates/partials/icon_grid.html.
  type SearchIndex = Record<string, string[]>;

  let lookup: SearchIndex | null = null;

  function applyFilter(): void {
    if (!lookup) return;

    const raw = input.value.trim().toLowerCase();

    const words = raw ? raw.split(/\s+/) : [];
    const links = document.querySelectorAll<HTMLAnchorElement>(".icon-grid > a");

    for (const el of links) {
      const k = lookup[el.id];
      if (!k) continue;
      const matches = words.every((w) => k.some((kw) => kw.indexOf(w) !== -1));
      const hiddenByDefault = el.hasAttribute("data-homepage-hidden");
      el.hidden = raw ? !matches : hiddenByDefault;
    }

    const tags = document.querySelectorAll<HTMLElement>(".tags .tag");
    for (const tag of tags) {
      const name = tag.querySelector<HTMLElement>(".tag-name");
      const text = (
        name ? (name.textContent ?? "") : (tag.textContent ?? "")
      ).toLowerCase();
      const hiddenByDefault = tag.hasAttribute("data-homepage-hidden");
      tag.hidden = raw ? text.indexOf(raw) === -1 : hiddenByDefault;
    }
  }

  fetch("/search-index.json")
    .then((response) => response.json() as Promise<SearchIndex>)
    .then((data) => {
      lookup = data;
      applyFilter();
    })
    .catch(() => {});

  input.addEventListener("input", applyFilter);
  input.addEventListener("search", applyFilter);
})();
